import { useMemo } from 'react';

import { portfolioHealthIndexOverviewMock } from '../__mocks__';
import {
  PHI_OVERVIEW_BFF_BEER_EVOLUTION_BREAKDOWN_KEY,
  PHI_OVERVIEW_BFF_PHI_PERFORMANCE_KEY,
  PHI_OVERVIEW_BFF_TOTAL_PHI_KEY,
} from '../../../constants';
import type {
  BeerEvolutionBreakdownData,
  PhiOverviewSectionDataResult,
  PhiPerformanceSection,
  TotalPhiCardData,
} from '../../../types';
import { normalizePhiOvertimeFromBff } from '../../../utils/normalizePhiOvertimeFromBff';
import {
  PHI_OVERVIEW_MOCK_FORCE_BY_SECTION,
  PHI_OVERVIEW_MOCK_ONLY,
} from '../constants';

export type PhiOverviewSectionKey =
  'totalPhi' | 'phiPerformance' | 'beerEvolutionBreakdown';

type PhiOverviewSectionDataMap = {
  totalPhi: TotalPhiCardData;
  phiPerformance: PhiPerformanceSection;
  beerEvolutionBreakdown: BeerEvolutionBreakdownData;
};

const noopRefetch = () => Promise.resolve();

function resolveMockView<T>(
  mockOnly: boolean,
  flags: { skeleton: boolean; error: boolean; empty: boolean },
  getReadyData: () => T,
): PhiOverviewSectionDataResult<T> {
  if (!mockOnly || flags.skeleton) {
    return { view: 'loading', data: null, refetch: noopRefetch };
  }

  if (flags.error) {
    return { view: 'error', data: null, refetch: noopRefetch };
  }

  if (flags.empty) {
    return { view: 'empty', data: null, refetch: noopRefetch };
  }

  return {
    view: 'ready',
    data: getReadyData(),
    refetch: noopRefetch,
  };
}

export function usePhiOverviewSectionData<K extends PhiOverviewSectionKey>(
  section: K,
): PhiOverviewSectionDataResult<PhiOverviewSectionDataMap[K]> {
  return useMemo(
    (): PhiOverviewSectionDataResult<PhiOverviewSectionDataMap[K]> =>
      resolveMockView(
        PHI_OVERVIEW_MOCK_ONLY,
        PHI_OVERVIEW_MOCK_FORCE_BY_SECTION[section],
        () => {
          if (section === 'totalPhi') {
            return portfolioHealthIndexOverviewMock[
              PHI_OVERVIEW_BFF_TOTAL_PHI_KEY
            ] as PhiOverviewSectionDataMap[K];
          }

          if (section === 'beerEvolutionBreakdown') {
            return portfolioHealthIndexOverviewMock[
              PHI_OVERVIEW_BFF_BEER_EVOLUTION_BREAKDOWN_KEY
            ] as PhiOverviewSectionDataMap[K];
          }

          const performanceSection =
            portfolioHealthIndexOverviewMock[
              PHI_OVERVIEW_BFF_PHI_PERFORMANCE_KEY
            ];

          return {
            overtime: normalizePhiOvertimeFromBff(performanceSection.overtime),
          } as PhiOverviewSectionDataMap[K];
        },
      ),
    [section],
  );
}
